import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { getUserByEmail, updateProfile, uploadResume, uploadPhoto } from '../services/api';
import { useAuth } from '../context/AuthContext';

export default function Profile() {
  const { user, signIn } = useAuth();
  const [profile, setProfile] = useState(null);
  const [form, setForm] = useState({});
  const [msg, setMsg] = useState('');
  const [error, setError] = useState('');
  const [resumeFile, setResumeFile] = useState(null);
  const [photoFile, setPhotoFile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState('info');

  useEffect(() => { load(); }, []);

  const load = async () => {
    try {
      const r = await getUserByEmail(user.email);
      setProfile(r.data);
      setForm({
        email: r.data.email,
        name: r.data.name || '',
        bio: r.data.bio || '',
        skills: r.data.skills || '',
        college: r.data.college || '',
        degree: r.data.degree || '',
        graduationYear: r.data.graduationYear || '',
        phone: r.data.phone || '',
        linkedinUrl: r.data.linkedinUrl || '',
        githubUrl: r.data.githubUrl || '',
      });
    } catch {}
    finally { setLoading(false); }
  };

  const saveProfile = async (e) => {
    e.preventDefault(); setMsg(''); setError('');
    try {
      const r = await updateProfile(form);
      if (r.data.success) {
        setMsg('Profile updated!');
        signIn({ ...user, name: form.name, profileCompletion: r.data.profileCompletion });
        load();
      }
    } catch { setError('Update failed.'); }
  };

  const saveResume = async (e) => {
    e.preventDefault();
    if (!resumeFile) return;
    try {
      const r = await uploadResume(user.email, resumeFile);
      if (r.data.success) { setMsg('Resume uploaded!'); load(); }
    } catch { setError('Upload failed.'); }
  };

  const savePhoto = async (e) => {
    e.preventDefault();
    if (!photoFile) return;
    try {
      const r = await uploadPhoto(user.email, photoFile);
      if (r.data.success) { setMsg('Photo uploaded!'); load(); }
    } catch { setError('Upload failed.'); }
  };

  if (loading) return <><Navbar /><div className="page"><div className="skeleton" style={{ height: '400px', borderRadius: '14px' }} /></div></>;

  const completion = profile?.profileCompletion || 0;

  return (
    <>
      <Navbar />
      <div className="page" style={{ maxWidth: '780px' }}>
        {msg && <div className="alert alert-success">{msg}</div>}
        {error && <div className="alert alert-error">{error}</div>}

        {/* Profile header */}
        <div className="card" style={{ marginBottom: '1.5rem', display: 'flex', gap: '1.5rem', alignItems: 'center', flexWrap: 'wrap' }}>
          <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: 'var(--surface2)', border: '2px solid var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem', flexShrink: 0 }}>
            {profile?.profilePhoto ? '📷' : profile?.name?.charAt(0) || '?'}
          </div>
          <div style={{ flex: 1 }}>
            <h2 style={{ fontSize: '1.3rem', marginBottom: '4px' }}>{profile?.name}</h2>
            <div style={{ color: 'var(--text2)', fontSize: '0.88rem', marginBottom: '10px' }}>{profile?.email}</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <div className="completion-bar" style={{ flex: 1, maxWidth: '220px' }}>
                <div className="completion-fill" style={{ width: `${completion}%` }} />
              </div>
              <span style={{ fontSize: '0.82rem', color: completion >= 80 ? 'var(--green)' : 'var(--text2)' }}>
                {completion}% complete
              </span>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="tabs">
          {[['info','Personal Info'],['skills','Skills & Links'],['resume','Resume & Photo']].map(([k,v]) => (
            <button key={k} className={`tab-btn ${tab === k ? 'active' : ''}`} onClick={() => setTab(k)}>{v}</button>
          ))}
        </div>

        {tab === 'info' && (
          <form onSubmit={saveProfile} className="card">
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
              {[
                { key: 'name', label: 'Full Name', type: 'text' },
                { key: 'phone', label: 'Phone', type: 'text' },
                { key: 'college', label: 'College / University', type: 'text' },
                { key: 'degree', label: 'Degree', type: 'text' },
                { key: 'graduationYear', label: 'Graduation Year', type: 'number' },
              ].map(f => (
                <div className="form-group" key={f.key}>
                  <label>{f.label}</label>
                  <input className="form-control" type={f.type} value={form[f.key] || ''}
                    onChange={e => setForm({ ...form, [f.key]: e.target.value })} />
                </div>
              ))}
            </div>
            <div className="form-group">
              <label>Bio</label>
              <textarea className="form-control" rows={3} placeholder="Tell companies about yourself…"
                value={form.bio} onChange={e => setForm({ ...form, bio: e.target.value })} />
            </div>
            <button className="btn btn-primary" type="submit" style={{ width: 'auto' }}>Save Changes</button>
          </form>
        )}

        {tab === 'skills' && (
          <form onSubmit={saveProfile} className="card">
            <div className="form-group">
              <label>Skills (comma-separated)</label>
              <input className="form-control" placeholder="React, Java, Python, Figma…"
                value={form.skills} onChange={e => setForm({ ...form, skills: e.target.value })} />
              {form.skills && (
                <div style={{ marginTop: '10px', display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
                  {form.skills.split(',').map((s, i) => s.trim() && (
                    <span key={i} className="tag">{s.trim()}</span>
                  ))}
                </div>
              )}
            </div>
            <div className="form-group">
              <label>LinkedIn URL</label>
              <input className="form-control" placeholder="https://linkedin.com/in/yourname"
                value={form.linkedinUrl} onChange={e => setForm({ ...form, linkedinUrl: e.target.value })} />
            </div>
            <div className="form-group">
              <label>GitHub URL</label>
              <input className="form-control" placeholder="https://github.com/yourname"
                value={form.githubUrl} onChange={e => setForm({ ...form, githubUrl: e.target.value })} />
            </div>
            <button className="btn btn-primary" type="submit" style={{ width: 'auto' }}>Save Changes</button>
          </form>
        )}

        {tab === 'resume' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <form onSubmit={saveResume} className="card">
              <h3 style={{ marginBottom: '1rem', fontSize: '1rem' }}>Upload Resume</h3>
              {profile?.resumePath && (
                <div className="alert alert-info" style={{ marginBottom: '1rem' }}>✅ Resume uploaded — you can replace it below.</div>
              )}
              <div className="form-group">
                <label>PDF or Word file (max 10 MB)</label>
                <input type="file" className="form-control" accept=".pdf,.doc,.docx"
                  onChange={e => setResumeFile(e.target.files[0])} />
              </div>
              <button className="btn btn-primary" type="submit" style={{ width: 'auto' }} disabled={!resumeFile}>
                Upload Resume
              </button>
            </form>

            <form onSubmit={savePhoto} className="card">
              <h3 style={{ marginBottom: '1rem', fontSize: '1rem' }}>Profile Photo</h3>
              <div className="form-group">
                <label>JPG or PNG (max 10 MB)</label>
                <input type="file" className="form-control" accept=".jpg,.jpeg,.png,.webp"
                  onChange={e => setPhotoFile(e.target.files[0])} />
              </div>
              <button className="btn btn-primary" type="submit" style={{ width: 'auto' }} disabled={!photoFile}>
                Upload Photo
              </button>
            </form>
          </div>
        )}
      </div>
    </>
  );
}
